import{_ as a,o,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"ATLAS Icon Library","description":"Search Home Assistant icon sets, browse icons and copy their names.","frontmatter":{"title":"ATLAS Icon Library","description":"Search Home Assistant icon sets, browse icons and copy their names."},"headers":[],"relativePath":"en/projects/atlas-plugins/icon-library.md","filePath":"en/projects/atlas-plugins/icon-library.md","lastUpdated":1793447386000}'),t={name:"en/projects/atlas-plugins/icon-library.md"};function i(r,e,c,l,d,p){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="atlas-icon-library" tabindex="-1">ATLAS Icon Library <a class="header-anchor" href="#atlas-icon-library" aria-label="Permalink to &quot;ATLAS Icon Library&quot;">​</a></h1><p>ATLAS Icon Library is a standalone plugin for searching and browsing icon sets. Icons appear in a grid of up to 20 columns; for large sets, the interface renders only the visible portion. Click an icon to copy its full name, such as <code>mdi:home</code> or <code>atlas:home</code>.</p><p>The MDI catalog is bundled with the plugin and is identified as an integrated source in the source field, rather than as a Home Assistant file path. SVG icons use the accent color by default, and the interface follows the browser&#39;s light or dark color scheme.</p><h2 id="loading-icon-sets" tabindex="-1">Loading icon sets <a class="header-anchor" href="#loading-icon-sets" aria-label="Permalink to &quot;Loading icon sets&quot;">​</a></h2><p>Since 0.1.9, grid size changes are coalesced to avoid an observed ResizeObserver feedback in WebKit. Partial rendering in a Safari 16.6 Ventura VM has not yet been confirmed fixed. Saved icon sets are preserved.</p><p>The plugin package includes the MDI catalog. Icon Studio collections and supported static Home Assistant icon sets can be imported as JavaScript files from the computer or loaded through File Studio from <code>/config/www/</code>. The scanner also searches subfolders, including <code>/config/www/community/</code> (available in Home Assistant as <code>/local/community/</code>). It considers supported JavaScript icon sets when “icon” appears in a filename or folder name, and combines files that use the same prefix. Examples include Hue, Selfh.st, BHA, Yandex, Custom Icons, KNX, Thermal Comfort and Custom Brand Icons. JavaScript files are parsed as data and never executed. Imported collections are stored locally in the browser.</p><p>Some legacy Home Assistant icon sets expose icon names through <code>window.customIcons</code> and can be displayed this way. The newer <code>window.customIconsets</code> interface has no general mechanism for listing every icon name in an arbitrary set. Such sets can only be displayed when they also provide a readable name list.</p><p>File Studio must grant access to <code>/config/www/</code>. The plugin does not need a Home Assistant token for this access.</p><h2 id="installation-and-source-code" tabindex="-1">Installation and source code <a class="header-anchor" href="#installation-and-source-code" aria-label="Permalink to &quot;Installation and source code&quot;">​</a></h2><p>Add this external repository in the ATLAS Plugin Manager:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/rockbaer2007/atlas-icon-library-plugin/main/repository.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>ATLAS 0.1.248 or newer is required because that release fixes external package installation.</p><p>See the <a href="https://github.com/rockbaer2007/atlas-icon-library-plugin" target="_blank" rel="noreferrer">GitHub repository</a> for source code and development notes.</p>',13)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
